function renderManualActivation(){const sel=$('manualUser');if(!sel)return;const old=sel.value;sel.innerHTML='<option value="">Select user</option>'+Object.keys(users).map(uid=>`<option value="${uid}">${esc(userLabel(uid))}</option>`).join('');if(users[old])sel.value=old;const uid=sel.value,u=users[uid]||{};$('manualFundButtons').innerHTML=FUND_KEYS.map(k=>`<div class="partner-row"><div><b>${FUND_INFO[k].name}</b><small>${isFundActive(u,k)?'Active':'Inactive'}</small></div><button class="tiny ${isFundActive(u,k)?'red':'green'}" data-manual-fund="${k}" data-manual-active="${isFundActive(u,k)?'0':'1'}">${isFundActive(u,k)?'Deactivate':'Activate'}</button></div>`).join('');document.querySelectorAll('[data-manual-fund]').forEach(b=>b.onclick=()=>manualFundSet(b.dataset.manualFund,b.dataset.manualActive==='1'));}
async function manualFundSet(k,active){const uid=$('manualUser').value;if(!uid)return toast('Select user.');await update(ref(db,`users/${uid}/fundActivations/${k}`),{active,activatedAt:active?now():null,activationMethod:'admin_manual',activatedBy:me.uid});if(active)await update(ref(db,`users/${uid}`),{accountStatus:'running',activationStatus:'verified'});await audit(active?'MANUAL_FUND_ACTIVATED':'MANUAL_FUND_DEACTIVATED',{uid,fund:k});toast(`${FUND_INFO[k].name} ${active?'activated':'deactivated'}.`);}
async function manualAll(active){const uid=$('manualUser').value;if(!uid)return toast('Select user.');const up={};FUND_KEYS.forEach(k=>{up[`users/${uid}/fundActivations/${k}/active`]=active;up[`users/${uid}/fundActivations/${k}/activationMethod`]='admin_manual';up[`users/${uid}/fundActivations/${k}/activatedAt`]=active?now():null});if(active){up[`users/${uid}/accountStatus`]='running';up[`users/${uid}/activationStatus`]='verified'}await update(ref(db),up);await audit(active?'MANUAL_ALL_FUNDS_ACTIVATED':'MANUAL_ALL_FUNDS_DEACTIVATED',{uid});toast(active?'All funds activated.':'All funds deactivated.');}
function partnerKey(n){return n.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
async function seedPartners(silent=false){
  const up={};
  PARTNER_NAMES.forEach((name,i)=>{const k=partnerKey(name);if(!partnerships[k])up[`partnerships/${k}`]={name,icon:(name.match(/[A-Za-z0-9]/)||['P'])[0].toUpperCase(),logo:`assets/partners/${k}.svg`,active:true,verified:false,order:i+1,message:''};});
  if(Object.keys(up).length)await update(ref(db),up);
  if(!silent)toast(Object.keys(up).length?'Company list loaded.':'Company list already loaded.');
}
async function addPartner(){const name=prompt('New company name');if(!name?.trim())return;const k=partnerKey(name);await set(ref(db,`partnerships/${k}`),{name:name.trim(),logo:'',icon:(name.match(/[A-Za-z0-9]/)||['P'])[0].toUpperCase(),active:true,verified:false,order:Object.keys(partnerships||{}).length+1,message:''});toast('Company added.');}
async function savePartner(k){const p=partnerships[k]||{};const name=prompt('Company name',p.name||k);if(!name)return;const logo=prompt('Logo path / URL (optional)',p.logo||'')??p.logo??'';const message=prompt('Admin note (optional)',p.message||'')??p.message??'';await update(ref(db,`partnerships/${k}`),{name:name.trim(),logo:logo.trim(),message:message.trim()});toast('Company updated.');}
function renderPartnerships(){const el=$('partnerList');if(!el)return;const q=($('partnerSearch')?.value||'').toLowerCase();const rows=Object.entries(partnerships||{}).filter(([k,p])=>!q||(p.name||k).toLowerCase().includes(q)).sort((a,b)=>(a[1].order||999)-(b[1].order||999));el.innerHTML=rows.map(([k,p])=>`<div class="partner-row"><div class="partner-icon">${p.logo?`<img src="${esc(p.logo)}" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span class="partner-fallback" style="display:none">${esc(p.icon||'P')}</span>`:esc(p.icon||'P')}</div><div class="grow"><b>${esc(p.name||k)}</b><small>${p.active?'Active':'Inactive'} • ${p.verified?'Verified':'Unverified'}</small></div><button class="tiny outline" data-partner-edit="${k}">Edit</button><button class="tiny ${p.active?'red':'green'}" data-partner-toggle="${k}">${p.active?'Deactivate':'Activate'}</button><button class="tiny outline" data-partner-verify="${k}">${p.verified?'Unverify':'Verify'}</button></div>`).join('')||'<div class="empty">Company list loading…</div>';document.querySelectorAll('[data-partner-edit]').forEach(b=>b.onclick=()=>savePartner(b.dataset.partnerEdit));document.querySelectorAll('[data-partner-toggle]').forEach(b=>b.onclick=()=>update(ref(db,`partnerships/${b.dataset.partnerToggle}`),{active:!partnerships[b.dataset.partnerToggle]?.active}));document.querySelectorAll('[data-partner-verify]').forEach(b=>b.onclick=()=>update(ref(db,`partnerships/${b.dataset.partnerVerify}`),{verified:!partnerships[b.dataset.partnerVerify]?.verified}));}

function renderUserFundAccounts(){const uid=$('fundAccountUser')?.value;if(!uid){$('fundAccountsBody').innerHTML='<div class="box empty">Select a user to view fund accounts.</div>';return;}const blocks=[...FUND_KEYS,'performance'].map(k=>{const arr=Object.entries(fundAccounts?.[uid]?.[k]||{});return `<article class="box"><h3>${esc(FUND_INFO[k].name)} <span class="pill ${k==='performance'?activeFundCount(users[uid])?'green':'gray':isFundActive(users[uid],k)?'green':'gray'}">${arr.length}/10 Accounts</span></h3>${arr.map(([id,a])=>`<div class="account-row"><b>${esc(a.holder||'Account')}</b><small>${esc(a.bank||'')} • ****${esc(String(a.account||'').slice(-4))} • IFSC ${esc(a.ifsc||'')} • ${esc(a.status||'active')}</small></div>`).join('')||'<div class="empty">No account saved.</div>'}</article>`;}).join('');$('fundAccountsBody').innerHTML=blocks;}

function renderLedger(){const rows=transactionRows().filter(t=>['credit','debit','commission'].includes(t.type));const stats=['credit','debit','commission'].map(type=>{const a=rows.filter(t=>t.type===type);return [type,a.length,a.reduce((s,t)=>s+Number(t.amount||0),0)]});$('ledgerStats').innerHTML=stats.map(([t,c,a])=>`<div class="mini-kpi"><small>${t[0].toUpperCase()+t.slice(1)} Transactions</small><b>${c.toLocaleString('en-IN')}</b><span>${money(a)}</span></div>`).join('');updateLedgerPreview();}
function updateLedgerPreview(){if(!$('ledgerPreview'))return;const amount=Number($('ledgerAmount')?.value||0),repeat=Math.max(0,Math.floor(Number($('ledgerRepeat')?.value||0))),type=$('ledgerType')?.value||'credit';$('ledgerPreview').innerHTML=amount>0&&repeat>0?`<b>${esc(type.toUpperCase())}: ${money(amount)} × ${repeat.toLocaleString('en-IN')} = ${money(amount*repeat)}</b><small>${repeat.toLocaleString('en-IN')} separate transaction IDs will be created for the selected user.</small>`:'Enter amount and repeat count to see preview.';}
async function addLedger(){
  const uid=$('ledgerUser').value,type=$('ledgerType').value,fund=$('ledgerFund')?.value||'gaming',amount=Number($('ledgerAmount').value),repeat=Math.floor(Number($('ledgerRepeat').value)),rawTitle=$('ledgerTitle').value.trim()||'Ledger Transaction',title=`Admin Manual • ${rawTitle}`;
  if(!uid||!users[uid])return toast('Select a valid user.');if(!['credit','debit','commission'].includes(type)||!Number.isFinite(amount)||amount<1||amount>100000000)return toast('Amount ₹1 se ₹10 crore tak rakhein.');if(!Number.isInteger(repeat)||repeat<1||repeat>MAX_LEDGER_REPEAT)return toast(`Repeat Count 1 se ${MAX_LEDGER_REPEAT.toLocaleString('en-IN')} tak rakhein.`);
  const total=amount*repeat,u=users[uid],oldBalance=Number(u.balance||0),oldCommission=Number(u.commission||0),rate=fundRate(fund),autoCommission=type==='credit'?Number((total*rate/100).toFixed(2)):0;
  if(type==='debit'&&total>oldBalance)return toast('Total debit user balance se zyada hai.');if(!confirm(`${userLabel(uid)}\n${type.toUpperCase()} ${money(amount)} × ${repeat} = ${money(total)}${type==='credit'?`\nAuto Commission ${rate}% = ${money(autoCommission)}`:''}`))return;
  showLoading(true);try{const batchId='BAT-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),base=now(),updates={};
    for(let i=1;i<=repeat;i++){const id='TXN-'+(base+i).toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase();updates[`transactions/${uid}/${id}`]={transactionId:id,title,type,amount,status:'completed',source:'admin_manual',fund,batchId,sequence:i,sequenceText:`${i}/${repeat}`,repeatCount:repeat,createdAt:base,availableAt:base+((i-1)*(type==='debit'?6000:3000)),createdBy:me.uid,createdByEmail:me.email||''};if(type==='credit'){const cid=id+'-COM',commission=Number((amount*rate/100).toFixed(2));updates[`transactions/${uid}/${cid}`]={transactionId:cid,title:`Commission • ${FUND_INFO[fund].name}`,type:'commission',amount:commission,status:'completed',source:'auto_commission',fund,batchId,sequence:i,sequenceText:`${i}/${repeat}`,repeatCount:repeat,createdAt:base,availableAt:base+((i-1)*3000),createdBy:me.uid,createdByEmail:me.email||''};}}
    if(type==='credit'){updates[`users/${uid}/balance`]=Number((oldBalance+total+autoCommission).toFixed(2));updates[`users/${uid}/commission`]=Number((oldCommission+autoCommission).toFixed(2));updates[`users/${uid}/withdrawableBalance`]=Number((Number(u.withdrawableBalance||oldCommission)+autoCommission).toFixed(2));}if(type==='debit')updates[`users/${uid}/balance`]=oldBalance-total;if(type==='commission'){updates[`users/${uid}/commission`]=oldCommission+total;updates[`users/${uid}/balance`]=oldBalance+total;updates[`users/${uid}/withdrawableBalance`]=Number(u.withdrawableBalance||oldCommission)+total;}
    updates[`ledgerBatches/${batchId}`]={batchId,uid,userCode:u.userCode||'',username:u.username||'',type,fund,amountPerTransaction:amount,repeatCount:repeat,totalEffect:total,autoCommission,rate,title,createdAt:base,createdBy:me.uid,createdByEmail:me.email||'',status:'completed'};await update(ref(db),updates);await audit('LEDGER_BATCH_CREATED',{uid,batchId,type,fund,amount,repeat,total,autoCommission});await adminActivity('Ledger batch created',`${userLabel(uid)} • ${type} • ${repeat} × ${money(amount)}`);toast(`${repeat} transactions created for selected user.`);}catch(e){console.error(e);toast(e.message)}finally{showLoading(false)}
}

function fundRate(k){const f=FUND_INFO[k];return Number(settings?.[f?.rateKey]??f?.fallbackRate??0);}
function splitRandomTotal(total,count){
  total=Math.round(Number(total)); count=Math.max(1,Math.floor(Number(count)));
  if(total<count)return null;
  const weights=Array.from({length:count},()=>0.35+Math.random()*1.65), sum=weights.reduce((a,b)=>a+b,0);
  let parts=weights.map(w=>Math.max(1,Math.floor(total*w/sum))), diff=total-parts.reduce((a,b)=>a+b,0),i=0;
  while(diff!==0){const j=i++%count;if(diff>0){parts[j]++;diff--;}else if(parts[j]>1){parts[j]--;diff++;}}
  for(let x=parts.length-1;x>0;x--){const j=Math.floor(Math.random()*(x+1));[parts[x],parts[j]]=[parts[j],parts[x]];} return parts;
}
async function addCombinedBatch(){
  const uid=$('comboUser').value,fund=$('comboFund').value,total=Number($('comboTotal').value),count=Math.floor(Number($('comboCount').value)),title=$('comboTitle').value.trim()||'Combined Fund Batch';
  if(!uid||!users[uid])return toast('Select a valid user.'); if(!FUND_INFO[fund]||!Number.isFinite(total)||total<1||total>100000000||!Number.isInteger(count)||count<1||count>500)return toast('Valid fund, total amount and 1-500 transactions enter karein.');
  const parts=splitRandomTotal(total,count);if(!parts)return toast('Total amount transaction count se kam nahi ho sakta.'); const rate=fundRate(fund),commissionTotal=parts.reduce((s,x)=>s+x*rate/100,0),u=users[uid],oldCommission=Number(u.commission||0);
  if(!confirm(`${userLabel(uid)}\n${FUND_INFO[fund].name}\nCredit total ${money(total)} in ${count} random entries\nMatching debit: ${money(total)}\nCommission (${rate}%): ${money(commissionTotal)}`))return;
  showLoading(true);try{const batchId='BAT-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),base=now(),updates={};
    let lastDisplayName=''; parts.forEach((amount,n)=>{const seq=n+1,stem=(base+seq).toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),commission=Number((amount*rate/100).toFixed(2)),displayName=randomDisplayName(lastDisplayName); lastDisplayName=displayName;
      [['credit',amount,'Credit',base+(n*5000)],['commission',commission,'Commission',base+(n*5000)+2000],['debit',amount,'Debit',base+(n*5000)+5000]].forEach(([type,val,label,availableAt],j)=>{const id=`TXN-${stem}-${j+1}`;const displayTitle=type==='commission'?`Commission • ${FUND_INFO[fund].name} • Your Commission`:(type==='debit'?`Debit • ${FUND_INFO[fund].name} • USDT Settlement`:`${label} • ${FUND_INFO[fund].name} • ${displayName}`);updates[`transactions/${uid}/${id}`]={transactionId:id,title:displayTitle,type,amount:val,status:'completed',source:'admin_combined_batch',fund,batchId,sequence:seq,sequenceText:`${seq}/${count}`,repeatCount:count,createdAt:base,availableAt,createdBy:me.uid,createdByEmail:me.email||''};});
    });
    /* V12: combined commission is applied live from scheduled ledger entries, not upfront. */ updates[`ledgerBatches/${batchId}`]={batchId,uid,userCode:u.userCode||'',username:u.username||'',type:'combined',fund,totalCredit:total,totalDebit:total,totalCommission:Number(commissionTotal.toFixed(2)),rate,repeatCount:count,title,createdAt:base,createdBy:me.uid,status:'completed'};
    await update(ref(db),updates);await audit('COMBINED_LEDGER_BATCH_CREATED',{uid,batchId,fund,total,count,rate,commissionTotal});await adminActivity('Combined batch created',`${userLabel(uid)} • ${FUND_INFO[fund].name} • ${count} transactions`);toast('Combined batch created successfully.');
  }catch(e){console.error(e);toast(e.message)}finally{showLoading(false)}
}
function renderTransactions(){const uid=$('txAdminUser')?.value||'all',type=$('txAdminType')?.value||'all',q=($('txBatchSearch')?.value||'').trim().toLowerCase();let arr=transactionRows();if(uid!=='all')arr=arr.filter(t=>t.uid===uid);if(type!=='all')arr=arr.filter(t=>t.type===type);if(q)arr=arr.filter(t=>[t.id,t.transactionId,t.batchId,t.title].some(x=>String(x||'').toLowerCase().includes(q)));$('transactionsBody').innerHTML=arr.slice(0,5000).map(t=>`<tr><td>${dt(t.createdAt)}</td><td>${esc(users[t.uid]?.username||t.username||'User')}</td><td>${esc(users[t.uid]?.userCode||t.userCode||t.uid.slice(0,10))}</td><td><span class="pill ${t.type==='debit'||t.type==='withdrawal'?'red':t.type==='commission'?'purple':'green'}">${esc(t.type||'credit')}</span></td><td>${money(t.amount)}</td><td><code>${esc(t.transactionId||t.id)}</code></td><td>${esc(t.batchId||'—')} ${t.sequenceText?`• ${esc(t.sequenceText)}`:''}</td><td>${esc(t.source||'system')}</td></tr>`).join('')||'<tr><td colspan="8">No transactions found.</td></tr>';}

function withdrawalCard(w){const u=users[w.uid]||{},dest=w.type==='upi'?w.details?.upi:`${w.details?.bank||''} • ****${String(w.details?.account||'').slice(-4)}`;return `<article class="payment-card"><div class="payment-main"><b>${esc(u.username||w.username||w.email||w.uid||'User')} • ${money(w.amount)}</b><small>${esc(w.withdrawalId||w.id)} • ${esc(w.type||'bank')} • ${esc(dest||'')}</small><div class="payment-meta"><span>${dt(w.createdAt)}</span><span class="pill ${w.status==='success'||w.status==='paid'?'green':w.status==='rejected'?'red':'orange'}">${esc(w.status||'pending')}</span></div>${w.rejectReason?`<div class="danger-note">Reason: ${esc(w.rejectReason)}</div>`:''}${w.referenceId?`<div class="success-note">Reference: ${esc(w.referenceId)}</div>`:''}</div>${w.status==='pending'?`<div class="row-actions"><button class="tiny green" data-wd-action="success" data-path="${esc(w._path)}">Success</button><button class="tiny red" data-wd-action="reject" data-path="${esc(w._path)}">Reject</button></div>`:''}</article>`;}
function renderWithdrawals(){$('withdrawalsBody').innerHTML=withdrawalRows().map(withdrawalCard).join('')||'<div class="box empty">No withdrawal requests.</div>';document.querySelectorAll('[data-wd-action]').forEach(b=>b.onclick=()=>reviewWithdrawal(b.dataset.path,b.dataset.wdAction));}
function findWithdrawalByPath(path){return withdrawalRows().find(w=>w._path===path);}
async function reviewWithdrawal(path,action){const w=findWithdrawalByPath(path);if(!w||w.status!=='pending')return toast('Only pending withdrawal can be processed.');const uid=w.uid,u=users[uid];if(!uid||!u)return toast('User not found.');try{showLoading(true);if(action==='reject'){const reason=prompt('Withdrawal reject reason','Details could not be verified')||'Rejected by Admin';const refund=Number(w.amount||0),refundUpdates={};refundUpdates[`${path}/status`]='rejected';refundUpdates[`${path}/rejectReason`]=reason;refundUpdates[`${path}/reviewedAt`]=now();refundUpdates[`${path}/reviewedBy`]=me.uid;refundUpdates[`${path}/refunded`]=true;await update(ref(db),refundUpdates);await userActivity(uid,'withdrawal','Withdrawal Rejected',`${money(w.amount)} • ${reason}`);await audit('WITHDRAWAL_REJECTED',{uid,id:w.id,amount:w.amount,reason});await adminActivity('Withdrawal rejected',`${userLabel(uid)} • ${money(w.amount)}`);toast('Withdrawal rejected.');}else{const amount=Number(w.amount||0);if(amount<=0)throw Error('Invalid withdrawal amount.');const referenceId=prompt('Payment / Reference ID (optional)','')||'ADMIN-'+Date.now().toString().slice(-10);const txid='WDRTX-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase();const updates={};updates[`${path}/status`]='success';updates[`${path}/referenceId`]=referenceId;updates[`${path}/completedAt`]=now();updates[`${path}/reviewedAt`]=now();updates[`${path}/reviewedBy`]=me.uid;updates[`transactions/${uid}/${txid}`]={transactionId:txid,title:'Withdrawal Successful',type:'withdrawal',amount,status:'completed',source:'withdrawal',withdrawalId:w.withdrawalId||w.id,referenceId,createdAt:now(),createdBy:me.uid};await update(ref(db),updates);await userActivity(uid,'withdrawal','Withdrawal Successful',`${money(amount)} • Reference ${referenceId}`);await audit('WITHDRAWAL_SUCCESS',{uid,id:w.id,amount,referenceId,txid});await adminActivity('Withdrawal successful',`${userLabel(uid)} • ${money(amount)} • ${referenceId}`);toast('Withdrawal marked successful.');}}catch(e){console.error(e);toast(e.message)}finally{showLoading(false)}}

