function renderNotifications(){$('activityFeedBody').innerHTML=feedRows().slice(0,150).map(a=>`<div class="feed-item"><b>${esc(a.title||'Activity')}</b><small>${esc(a.message||'')} • ${dt(a.createdAt)}</small></div>`).join('')||'<div class="empty">No activity.</div>';}
async function sendNotification(){const target=$('notifyUser').value,title=$('notifyTitle').value.trim(),message=$('notifyMessage').value.trim();if(!title||!message)return toast('Title and message required.');const path=target==='all'?'globalNotifications':`notifications/${target}`;const r=push(ref(db,path));await set(r,{id:r.key,title,message,createdAt:now(),createdBy:me.uid});await audit('NOTIFICATION_SENT',{target,title});await adminActivity('Notification sent',`${target==='all'?'All Users':userLabel(target)} • ${title}`);$('notifyTitle').value='';$('notifyMessage').value='';toast('Notification sent.');}
function renderSettings(){if(document.activeElement!==$('minWithdrawal'))$('minWithdrawal').value=settings.minWithdrawal??0;if(document.activeElement!==$('appTagline'))$('appTagline').value=settings.appTagline||'Bharat ka Vishwas, Tirange ke Saath';if(document.activeElement!==$('paymentWarning'))$('paymentWarning').value=settings.paymentWarning||'Fake / invalid UTR submit na karein. Repeated rejection par penalty aur ID block ho sakti hai.';}
async function saveGeneral(){const d={minWithdrawal:Number($('minWithdrawal').value||0),appTagline:$('appTagline').value.trim(),paymentWarning:$('paymentWarning').value.trim()};await update(ref(db,'settings'),d);await audit('GENERAL_SETTINGS_UPDATED',d);toast('General settings saved.');}

function renderBanks(){const q=($('bankSearch')?.value||'').trim().toLowerCase();const arr=Object.entries(banks||{}).filter(([id,b])=>!q||(b.name||id).toLowerCase().includes(q)).sort((a,b)=>(a[1]?.name||'').localeCompare(b[1]?.name||''));$('bankDirectoryBody').innerHTML=arr.map(([id,b])=>`<div class="bank-row"><div><b>${esc(b.name||id)}</b><small>ID ${esc(id)}</small></div><button class="tiny ${b.enabled===false?'orange':'green'}" data-bank-toggle="${esc(id)}">${b.enabled===false?'Enable':'Disable'}</button></div>`).join('')||'<div class="box empty">No banks found.</div>';document.querySelectorAll('[data-bank-toggle]').forEach(b=>b.onclick=()=>toggleBank(b.dataset.bankToggle));}
async function seedBanks(){if(!confirm(`Seed ${BANK_SEED.length} starter bank entries? Existing entries with same IDs will be updated.`))return;showLoading(true);try{const updates={};BANK_SEED.forEach(b=>updates[`bankDirectory/${b.id}`]={name:b.name,enabled:b.enabled!==false,source:'starter-directory'});await update(ref(db),updates);await audit('BANK_DIRECTORY_SEEDED',{count:BANK_SEED.length});toast(`${BANK_SEED.length} bank entries seeded.`);}catch(e){toast(e.message)}finally{showLoading(false)}}
async function addBank(){const name=(prompt('Bank name')||'').trim();if(!name)return;const id='bank-'+Date.now().toString(36);await set(ref(db,`bankDirectory/${id}`),{name,enabled:true,source:'admin-added',createdAt:now()});await audit('BANK_ADDED',{id,name});toast('Bank added.');}
async function toggleBank(id){const b=banks[id];if(!b)return;await update(ref(db,`bankDirectory/${id}`),{enabled:b.enabled===false});await audit('BANK_STATUS_CHANGED',{id,name:b.name,enabled:b.enabled===false});}
function renderAudit(){$('auditBody').innerHTML=auditRows().slice(0,1000).map(a=>`<div class="feed-item"><b>${esc(a.action||'ADMIN ACTION')}</b><small>${esc(a.adminEmail||'')} • ${dt(a.createdAt)}<br>${esc(JSON.stringify(a.details||{}))}</small></div>`).join('')||'<div class="box empty">No audit logs.</div>';}

async function migrateLegacyData(){if(!confirm('Legacy flat activation payment / withdrawal records ko new user-wise structure me migrate karna hai? Original flat records successful copy ke baad remove honge.'))return;showLoading(true);let pay=0,wd=0;try{const paymentUpdates={},paymentRemovals=[];for(const p of flattenMaybeNested(activationPayments,'payment').filter(x=>x._legacy&&!x.migratedTo)){if(!p.uid)continue;const obj={...p};delete obj._path;delete obj._legacy;obj.planKey=obj.planKey||'allFunds';obj.planName=obj.planName||PLAN_INFO[obj.planKey]?.name||'Legacy Activation';obj.id=p.id;paymentUpdates[`activationPayments/${p.uid}/${p.id}`]=obj;paymentRemovals.push(`activationPayments/${p.id}`);pay++;}for(const w of flattenMaybeNested(withdrawals,'withdrawal').filter(x=>x._legacy&&!x.migratedTo)){if(!w.uid)continue;const obj={...w};delete obj._path;delete obj._legacy;obj.id=w.id;paymentUpdates[`withdrawals/${w.uid}/${w.id}`]=obj;paymentRemovals.push(`withdrawals/${w.id}`);wd++;}if(Object.keys(paymentUpdates).length)await update(ref(db),paymentUpdates);const removals={};paymentRemovals.forEach(p=>removals[p]=null);if(Object.keys(removals).length)await update(ref(db),removals);await audit('LEGACY_DATA_MIGRATED',{payments:pay,withdrawals:wd});toast(`Migration complete: ${pay} payments, ${wd} withdrawals.`);}catch(e){console.error(e);toast(e.message)}finally{showLoading(false)}}

function imageFileToDataUrl(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(file.size>6*1024*1024)return reject(Error('QR image too large.'));const r=new FileReader();r.onerror=()=>reject(Error('Could not read image.'));r.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('Invalid image.'));img.onload=()=>{const max=700,scale=Math.min(1,max/img.width,max/img.height),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.84));};img.src=r.result;};r.readAsDataURL(file);});}

function bindStatic(){
  initMenu();
  $('adminLoginBtn').onclick=async()=>{try{showLoading(true);$('adminMsg').textContent='';const email=$('adminEmail').value.trim(),pass=$('adminPass').value;if(!email||!pass)throw Error('Email and password required.');await signInWithEmailAndPassword(auth,email,pass);}catch(e){console.error('Admin login failed',e);$('adminMsg').textContent=(e?.code?e.code+': ':'')+(e?.message||'Login failed.');}finally{showLoading(false)}};
  $('adminLogoutBtn').onclick=()=>signOut(auth);
  $('userSearch').addEventListener('input',renderUsers);
  $('saveFundRatesBtn').onclick=()=>saveFundRates().catch(e=>toast(e.message));$('saveActivationPlansBtn').onclick=()=>saveActivationPlans().catch(e=>toast(e.message));
  $('overrideUser').onchange=loadOverrideForm;$('overridePlan').onchange=loadOverrideForm;$('overrideQrFile').onchange=async e=>{try{overrideQrDraft=await imageFileToDataUrl(e.target.files?.[0]);$('overrideQrPreview').innerHTML=overrideQrDraft?`<img src="${esc(overrideQrDraft)}" class="qr-preview-small">`:'';}catch(err){toast(err.message)}};
  $('saveOverrideBtn').onclick=()=>saveOverride().catch(e=>toast(e.message));$('resetOverrideBtn').onclick=()=>resetOverride().catch(e=>toast(e.message));$('fundAccountUser').onchange=renderUserFundAccounts;$('manualUser').onchange=renderManualActivation;$('manualActivateAll').onclick=()=>manualAll(true);$('manualDeactivateAll').onclick=()=>manualAll(false);if($('seedPartnersBtn'))$('seedPartnersBtn').onclick=()=>seedPartners();if($('addPartnerBtn'))$('addPartnerBtn').onclick=()=>addPartner();if($('partnerSearch'))$('partnerSearch').oninput=renderPartnerships;
  ['ledgerAmount','ledgerRepeat','ledgerType','ledgerFund'].forEach(id=>$(id).addEventListener('input',updateLedgerPreview));$('addLedgerBtn').onclick=()=>addLedger();$('comboCreateBtn').onclick=()=>addCombinedBatch();
  ['txAdminUser','txAdminType','txBatchSearch'].forEach(id=>$(id).addEventListener(id==='txBatchSearch'?'input':'change',renderTransactions));
  $('saveBonusBtn').onclick=()=>saveBonus().catch(e=>toast(e.message));$('savePoliciesBtn').onclick=()=>savePolicies().catch(e=>toast(e.message));$('sendNotificationBtn').onclick=()=>sendNotification().catch(e=>toast(e.message));$('saveGeneralBtn').onclick=()=>saveGeneral().catch(e=>toast(e.message));
  $('seedBanksBtn').onclick=()=>seedBanks();$('addBankBtn').onclick=()=>addBank().catch(e=>toast(e.message));$('bankSearch').oninput=renderBanks;
  const migrate=document.createElement('button');migrate.className='btn outline';migrate.textContent='Migrate Legacy Payment / Withdrawal Data';migrate.onclick=()=>migrateLegacyData();$('panel-settings').querySelector('.box')?.appendChild(migrate);
}

function subscribe(path,cb){return onValue(ref(db,path),s=>{cb(s.val()||{});render();},e=>{console.error(path,e);$('syncState').textContent='● Permission / Sync Error';});}

bindStatic();
onAuthStateChanged(auth,async user=>{
  me=user||null;
  if(!user){$('loginView').classList.remove('hidden');$('panelView').classList.add('hidden');return;}
  showLoading(true);
  try{
    const a=await get(ref(db,`admins/${user.uid}`));
    if(!a.exists()||!['admin','superadmin'].includes(a.val()?.role)){await signOut(auth);$('adminMsg').textContent='Admin access denied.';return;}
    $('adminIdentity').textContent=`${user.email||''} • ${a.val()?.role||'admin'}`;$('loginView').classList.add('hidden');$('panelView').classList.remove('hidden');
    subscribe('users',v=>users=v);subscribe('activationPayments',v=>activationPayments=v);subscribe('withdrawals',v=>withdrawals=v);subscribe('transactions',v=>transactions=v);subscribe('fundAccounts',v=>fundAccounts=v);subscribe('fundSetupCodes',v=>fundSetupCodes=v);subscribe('userActivationOverrides',v=>overrides=v);subscribe('settings',v=>settings=v);subscribe('auditLogs',v=>audits=v);subscribe('bonusClaims',v=>bonusClaims=v);subscribe('adminActivityFeed',v=>adminFeed=v);subscribe('bankDirectory',v=>banks=v);subscribe('verificationSubmissions',v=>verificationSubmissions=v);subscribe('partnerships',v=>{partnerships=v;});
    $('syncState').textContent='● Live';
  }catch(e){console.error(e);$('adminMsg').textContent=e.message;}finally{showLoading(false)}
});

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
